const lockToolCallKey = `-- name: LockToolCallKey :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// Serializa pedidos de aprovação concorrentes da mesma chamada (mesmo chamador, tool e argumentos).
func (q *Queries) LockToolCallKey(ctx context.Context, key string) error {
	_, err := q.db.Exec(ctx, lockToolCallKey, key)
	return err
}

const lockToolCatalog = `-- name: LockToolCatalog :exec
SELECT pg_advisory_xact_lock(hashtextextended('tool_catalog:' || $1::text, 0))
`

// Serializa descobertas concorrentes da mesma integração (a transação segura o lock).
func (q *Queries) LockToolCatalog(ctx context.Context, integrationID string) error {
	_, err := q.db.Exec(ctx, lockToolCatalog, integrationID)
	return err
}

