const pruneToolInvocationsBefore = `-- name: PruneToolInvocationsBefore :execrows
DELETE FROM tool_invocations WHERE created_at < $1
`

func (q *Queries) PruneToolInvocationsBefore(ctx context.Context, before time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, pruneToolInvocationsBefore, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const pruneToolInvocationsOverCap = `-- name: PruneToolInvocationsOverCap :execrows
DELETE FROM tool_invocations t
USING (
    SELECT id FROM (
        SELECT id, row_number() OVER (PARTITION BY company_id ORDER BY created_at DESC, id DESC) AS rn
        FROM tool_invocations
    ) x WHERE x.rn > $1::bigint
) d
WHERE t.id = d.id
`

// Mantém só as @keep mais recentes de cada empresa.
func (q *Queries) PruneToolInvocationsOverCap(ctx context.Context, keep int64) (int64, error) {
	result, err := q.db.Exec(ctx, pruneToolInvocationsOverCap, keep)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

